from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    pieces = []

    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == bg:
                continue
            seen[r][c] = True
            stack = [(r, c)]
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x, grid[y][x]))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if not (dy or dx):
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != bg:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
            y0 = min(y for y, x, v in cells)
            x0 = min(x for y, x, v in cells)
            norm = [(y - y0, x - x0, v) for y, x, v in cells]
            pieces.append(norm)

    # A small piece which occurs verbatim in a larger piece is a key, not
    # part of the picture to be assembled.
    keys = set()
    for i, a in enumerate(pieces):
        if len(a) < 3:
            continue
        for j, b in enumerate(pieces):
            if i == j or len(a) >= len(b):
                continue
            found = False
            for ay, ax, av in a:
                for by, bx, bv in b:
                    if av != bv:
                        continue
                    dy, dx = by - ay, bx - ax
                    aset = {(y + dy, x + dx): v for y, x, v in a}
                    bdict = {(y, x): v for y, x, v in b}
                    if all(bdict.get(p) == v for p, v in aset.items()):
                        found = True
                        break
                if found:
                    break
            if found:
                keys.add(i)
                break

    ids = [i for i in range(len(pieces)) if i not in keys]
    if not ids:
        ids = list(range(len(pieces)))

    # Begin with the largest non-key fragment.
    first = max(ids, key=lambda i: len(pieces[i]))
    placed = {first: (0, 0)}
    remaining = set(ids)
    remaining.remove(first)

    def score(a, b, dy, dx):
        bd = {(y, x): v for y, x, v in b}
        same = conflict = 0
        for y, x, v in a:
            q = (y + dy, x + dx)
            if q in bd:
                if bd[q] == v:
                    same += 1
                else:
                    conflict += 1
        return same, conflict

    while remaining:
        best = None
        for i in remaining:
            a = pieces[i]
            for j, (jy, jx) in placed.items():
                b = [(y + jy, x + jx, v) for y, x, v in pieces[j]]
                for ay, ax, av in a:
                    for by, bx, bv in b:
                        if av != bv:
                            continue
                        dy, dx = by - ay, bx - ax
                        same, conflict = score(a, b, dy, dx)
                        if same < 3 or same <= conflict:
                            continue
                        candidate = (same - 3 * conflict, same, -conflict, -i, i, dy, dx)
                        if best is None or candidate > best:
                            best = candidate
        if best is None:
            # This fallback is not normally needed; retain any disconnected
            # fragment to the right rather than discarding information.
            i = min(remaining)
            maxx = max(x + placed[j][1] for j in placed for y, x, v in pieces[j])
            placed[i] = (0, maxx + 2)
        else:
            i, dy, dx = best[-3], best[-2], best[-1]
            placed[i] = (dy, dx)
        remaining.remove(i)

    cells = {}
    for i, (dy, dx) in placed.items():
        for y, x, v in pieces[i]:
            p = (y + dy, x + dx)
            if p not in cells:
                cells[p] = v
    y0 = min(y for y, x in cells)
    x0 = min(x for y, x in cells)
    y1 = max(y for y, x in cells)
    x1 = max(x for y, x in cells)
    out = [[bg] * (x1 - x0 + 1) for _ in range(y1 - y0 + 1)]
    for (y, x), v in cells.items():
        out[y - y0][x - x0] = v
    return out
